1: import type { Vec3 } from '../contracts/math';
2: 
3: export interface CameraRaycastHit {
4:   distance: number;
5: }
6: 
7: export interface CameraRaycaster {
8:   cast(origin: Vec3, direction: Vec3, maxDistance: number): CameraRaycastHit | null;
9: }
10: 
11: export interface CameraCollisionOptions {
12:   clearance?: number;
13:   minDistance?: number;
14: }
15: 
16: const DEFAULT_CLEARANCE = 0.18;
17: const DEFAULT_MIN_DISTANCE = 0.35;
18: const EPSILON = 1e-6;
19: 
20: export function resolveCameraPosition(
21:   target: Vec3,
22:   desiredPosition: Vec3,
23:   raycaster: CameraRaycaster,
24:   options: CameraCollisionOptions = {},
25: ): Vec3 {
26:   const dx = desiredPosition.x - target.x;
27:   const dy = desiredPosition.y - target.y;
28:   const dz = desiredPosition.z - target.z;
29:   const distance = Math.hypot(dx, dy, dz);
30: 
31:   if (!Number.isFinite(distance) || distance <= EPSILON) return { ...desiredPosition };
32: 
33:   const direction = { x: dx / distance, y: dy / distance, z: dz / distance };
34:   const hit = raycaster.cast(target, direction, distance);
35:   if (!hit || !Number.isFinite(hit.distance) || hit.distance < 0 || hit.distance > distance) {
36:     return { ...desiredPosition };
37:   }
38: 
39:   const clearance = Math.max(0, options.clearance ?? DEFAULT_CLEARANCE);
40:   const minDistance = Math.max(0, Math.min(options.minDistance ?? DEFAULT_MIN_DISTANCE, distance));
41:   const safeDistance = Math.min(distance, Math.max(minDistance, hit.distance - clearance));
42: 
43:   return {
44:     x: target.x + direction.x * safeDistance,
45:     y: target.y + direction.y * safeDistance,
46:     z: target.z + direction.z * safeDistance,
47:   };
48: }
